import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Geometria di Riemann","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/f_geometria-del-piano-euclideo/ff/ffebd.md","filePath":"lezioni/f_geometria-del-piano-euclideo/ff/ffebd.md"}`),a={name:`lezioni/f_geometria-del-piano-euclideo/ff/ffebd.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="geometria-di-riemann" tabindex="-1">Geometria di Riemann <a class="header-anchor" href="#geometria-di-riemann" aria-label="Permalink to “Geometria di Riemann”">​</a></h1><blockquote><p>È una delle più strane, ma più vicina delle altre alla geometria del mondo reale</p></blockquote><p>Consideriamo come piano la superficie di una sfera. Consideriamo come punto l&#39;insieme di <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>2</mn></mrow><annotation encoding="application/x-tex">2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span> punti opposti sulla sfera (polo nord e sud assieme formano un punto). Consideriamo come retta un qualunque cerchio massimo (cioè tipo l&#39;equatore).</p><p>Con queste convenzioni <strong>valgono</strong> tutti i postulati eccetto il <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>5</mn><mi>o</mi></msup></mrow><annotation encoding="application/x-tex">5^o</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6644em;"></span><span class="mord"><span class="mord">5</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">o</span></span></span></span></span></span></span></span></span></span></span>: infatti <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>2</mn></mrow><annotation encoding="application/x-tex">2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span> rette qualunque sulla sfera avranno sempre un punto in comune: dove i cerchi si tagliano.</p><p>E quindi non potrà mai esistere una retta parallela a un&#39;altra.</p><p>In questa geometria, da un punto non si può mandare nessuna retta parallela.</p>`,6)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};